{
  "apiVersion": "1.0",
   "title": "Livestock Health Assistant API",
   "description": "API for livestock health assistant to provide guidance to farmers",
   "tags": [
      "livestock",
      "health",
      "assistant",
      "farmer"
   ],
   "servers": [
      {
         "url": "https://example.com/livestock-health-assistant-api"
      }
   ],
   "paths": {
      "/ask": {
         "post": {
            "summary": "Ask for guidance on livestock health",
            "description": "Provide information about the animal's symptoms and receive guidance on possible conditions and care steps",
            "parameters": [
               {
                  "name": "userInput",
                  "in": "body",
                  "description": "User's message about the animal's symptoms",
                  "required": true,
                  "schema": {
                     "type": "string"
                  }
               }
            ],
            "responses": {
               "200": {
                  "description": "Guidance on possible conditions and care steps",
                  "schema": {
                     "$ref": "#/components/schemas/MedicalResponse"
                  }
               },
               "400": {
                  "description": "Invalid input",
                  "schema": {
                     "$ref": "#/components/schemas/Error"
                  }
               }
            }
         }
      }
   },
   "components": {
      "schemas": {
         "MedicalResponse": {
            "type": "object",
            "properties": {
               "responseType": {
                  "type": "string",
                  "enum": [
                     "medical"
                  ]
               },
               "severity": {
                  "type": "string",
                  "enum": [
                     "low",
                     "medium",
                     "urgent"
                  ]
               },
               "possibleConditions": {
                  "type": "array",
                  "items": {
                     "type": "string"
                  }
               },
               "chatReply": {
                  "type": "string"
               },
               "careSteps": {
                  "type": "array",
                  "items": {
                     "type": "string"
                  }
               },
               "treatmentPlan": {
                  "type": "object",
                  "properties": {
                     "immediateCare": {
                        "type": "array",
                        "items": {
                           "type": "string"
                        }
                     },
                     "supportiveCare": {
                        "type": "array",
                        "items": {
                           "type": "string"
                        }
                     },
                     "whenToCallVet": {
                        "type": "array",
                        "items": {
                           "type": "string"
                        }
                     },
                     "monitoringChecklist": {
                        "type": "array",
                        "items": {
                           "type": "string"
                        }
                     },
                     "followUpQuestions": {
                        "type": "array",
                        "items": {
                           "type": "string"
                        }
                     }
                  }
               },
               "disclaimer": {
                  "type": "string"
               }
            }
         },
         "Error": {
            "type": "object",
            "properties": {
               "error": {
                  "type": "string"
               }
            }
         }
      }
   }
}

